-- Align catalogue labels with the r10 figures and manuscript r15 (2026-11-22).
-- Metadata only: no result rows, fitted estimates, source hashes or publication flags change.
-- Apply after review, in the same release as the Student-t collections.
begin;
do $check$
declare updates jsonb := $mapping$[{"id": "manuscript/asah1_labels", "old_title": "Figure S15b · ASAH1 glycofeature identities", "old_description": "A01–A20 identify distinct peptide-plus-glycan features. All 20 conditional estimates are retained.", "title": "Figure S25b · ASAH1 glycofeature identities", "description": "A01–A20 identify distinct peptide-plus-glycan features. All 20 conditional estimates are retained."}, {"id": "manuscript/candidate_sensitivity_coverage", "old_title": "Figure S14b · candidate sensitivity coverage", "old_description": "Covariate-sensitivity availability for 27 of 81 primary conditional candidates: 24 selected features plus three ASAH1 glycoforms.", "title": "Figure S20 · candidate sensitivity coverage", "description": "Covariate-sensitivity availability for 27 of 81 primary conditional candidates: 24 selected features plus three ASAH1 glycoforms."}, {"id": "manuscript/glyco_labels", "old_title": "Figure 6d · glycofeature labels", "old_description": "The 20 displayed glycofeatures with complete peptide and glycan identities and both effect columns.", "title": "Figure 6e · glycofeature labels", "description": "The 20 displayed glycofeatures with complete peptide and glycan identities and both effect columns."}, {"id": "manuscript/phospho_labels", "old_title": "Figure 6c · phosphosite labels", "old_description": "The 14 displayed phosphosites with complete feature identities and both effect columns.", "title": "Figure 6d · phosphosite labels", "description": "The 14 displayed phosphosites with complete feature identities and both effect columns."}, {"id": "manuscript/ptm_calibration_completion", "old_title": "Figure S21b · calibration sample counts", "old_description": "250 completed simulated datasets; 249 numerically adequate.", "title": "Figure S19b · calibration sample counts", "description": "250 completed simulated datasets; 249 numerically adequate."}, {"id": "manuscript/ptm_calibration_replicates", "old_title": "Figures S18–S20 · per-replicate calibration metrics", "old_description": "250 simulated datasets × six quantities. Literal null denotes the null scenario; these are simulated quantities, not patient records.", "title": "Figures S16–S18 · per-replicate calibration metrics", "description": "250 simulated datasets × six quantities. Literal null denotes the null scenario; these are simulated quantities, not patient records."}, {"id": "manuscript/ptm_calibration_summary", "old_title": "Figures S18–S20 · PTM calibration summary", "old_description": "Six quantities, five scenarios and two scopes: all completed versus numerically adequate fits. Figure S18 shows coverage, S19 bias and S20 RMSE. Coverage bars are Wilson confidence intervals, not HDIs. No screen-wide false-discovery control.", "title": "Figures S16–S18 · PTM calibration summary", "description": "Six quantities, five scenarios and two scopes: all completed versus numerically adequate fits. Figure S16 shows coverage, S17 bias and S18 RMSE. Coverage bars are Wilson confidence intervals, not HDIs. No screen-wide false-discovery control."}, {"id": "manuscript/ptm_calibration_templates", "old_title": "Figures S18–S20 · calibration by template", "old_description": "Separate phospho and glyco template results; aggregate summaries across simulated replicates.", "title": "Figures S16–S18 · calibration by template", "description": "Separate phospho and glyco template results; aggregate summaries across simulated replicates."}, {"id": "manuscript/ptm_heatmap_lookup", "old_title": "Figures 6c,d · PTM heatmap identities and estimates", "old_description": "All 14 phospho and top 20 of 67 glyco conditional candidates. Gene, site/peptide/glycan, both effects and pointwise HDIs; magnitude-ranked without multiplicity control.", "title": "Figures 6d,e · PTM candidate identities and estimates", "description": "All 14 phospho and top 20 of 67 glyco conditional candidates. Gene, site/peptide/glycan, both effects and pointwise HDIs; magnitude-ranked without multiplicity control."}, {"id": "manuscript/ptm_sbc_bins", "old_title": "Figure S21a · SBC rank histogram counts", "old_description": "Pointwise 95% binomial reference limits are not simultaneous bands or a formal calibration test.", "title": "Figure S19a · SBC rank histogram counts", "description": "Pointwise 95% binomial reference limits are not simultaneous bands or a formal calibration test."}, {"id": "manuscript/ptm_sbc_values", "old_title": "Figure S21a · SBC ranks", "old_description": "Prior-predictive SBC ranks for 50 simulated datasets × six quantities. Randomized ties use seed 20261004.", "title": "Figure S19a · SBC ranks", "description": "Prior-predictive SBC ranks for 50 simulated datasets × six quantities. Randomized ties use seed 20261004."}, {"id": "manuscript/rna_heatmap_values", "old_title": "Figure 3a · RNA heatmap values", "old_description": "Displayed continuous RNA coefficients for the 24 selected signature rows. Unmodeled combinations remain missing. The named examples in Figures 3b–e are available in the compartment RNA effects collections.", "title": "Orthogonal patient-effect model · signature heatmap values", "description": "Displayed coefficients from the orthogonal patient-effect model for the 24 signature rows shown in an earlier version of Figure 3a. Figure 3 now uses the Student-t intercept model; its estimates are in the RNA effects collections. Unmodeled combinations remain missing."}, {"id": "manuscript/rna_protein_heatmap_values", "old_title": "Figure 5e · RNA–protein heatmap values", "old_description": "Displayed paired-model RNA and protein slopes and direct protein-minus-RNA contrasts.", "title": "Figure 5d · RNA–protein values for the displayed gene sets", "description": "Displayed paired-model RNA and protein slopes and direct protein-minus-RNA contrasts."}, {"id": "manuscript/rna_protein_labels", "old_title": "Figure 5e · RNA–protein programme labels", "old_description": "RP01–RP16 link displayed labels to unique measured programmes and source signatures.", "title": "Figure 5d · RNA–protein programme labels", "description": "RP01–RP16 link displayed labels to unique measured programmes and source signatures."}]$mapping$;
begin
 if exists (
   select 1 from jsonb_to_recordset(updates) as u(id text, old_title text, old_description text, title text, description text)
   left join public.atlas_web_datasets d on d.id=u.id
   where d.id is null or d.run_key <> 'manuscript_ptm_20261004'
      or d.title not in (u.old_title,u.title)
      or d.description not in (u.old_description,u.description)
 ) then raise exception 'Manuscript catalogue changed or required collections are missing; review before updating'; end if;
 update public.atlas_web_datasets d set title=u.title, description=u.description
 from jsonb_to_recordset(updates) as u(id text, title text, description text)
 where d.id=u.id and (d.title,d.description) is distinct from (u.title,u.description);
end $check$;
update public.atlas_figure_specs set title='Figures S16–S18 · PTM calibration',
 parameters=parameters || '{"figure_references":{"calibration_coverage":"S16","calibration_bias":"S17","calibration_rmse":"S18"}}'::jsonb
 where figure_key='manuscript/PTM_calibration';
update public.atlas_figure_specs set title='Figures 6d,e · supported PTM BMI effects',
 parameters=parameters || '{"figure_references":{"phospho":"6d","glyco":"6e"}}'::jsonb
 where figure_key='manuscript/PTM_primary';
commit;
